import{_ as o,o as r,c as e,a5 as s}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"SqlMapConfig.xml配置文件","description":"","frontmatter":{"title":"SqlMapConfig.xml配置文件","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/SqlMapConfig.xml配置文件.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/SqlMapConfig.xml配置文件.md"}'),n={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/SqlMapConfig.xml配置文件.md"};function a(g,t,m,p,l,u){return r(),e("div",null,[...t[0]||(t[0]=[s('<div><p><strong>6.1</strong> <strong>配置内容</strong><strong>6.1.1 SqlMapConfig.xml</strong> <strong>中配置的内容和顺序</strong><strong>-properties</strong>**（属性）** <strong>--property</strong> -settings（全局配置参数） --setting <strong>-typeAliases</strong>**（类型别名）** <strong>--typeAliase</strong><strong>--package</strong> -typeHandlers（类型处理器） -objectFactory（对象工厂） -plugins（插件） -environments（环境集合属性对象） --environment（环境子属性对象） ---transactionManager（事务管理） ---dataSource（数据源） <strong>-mappers</strong>**（映射器）** <strong>--mapper</strong><strong>--package</strong><strong>6.2 properties</strong>**（属性）** 在使用 properties 标签配置时，我们可以采用两种方式指定属性配置。 <strong>6.2.1</strong> <strong>第一种</strong> &lt;properties&gt; &lt;property name=<em>&quot;jdbc.driver&quot;</em> value=<em>&quot;com.mysql.jdbc.Driver&quot;</em>/&gt; &lt;property name=<em>&quot;jdbc.url&quot;</em> value=<em>&quot;jdbc:mysql://localhost:3306/eesy&quot;</em>/&gt;传智播客——专注于 Java、.Net 和 Php、网页平面设计工程师的培训 &lt;property name=<em>&quot;jdbc.username&quot;</em> value=<em>&quot;root&quot;</em>/&gt; &lt;property name=<em>&quot;jdbc.password&quot;</em> value=<em>&quot;1234&quot;</em>/&gt; &lt;/properties&gt; <strong>6.2.2</strong> <strong>第二种</strong><strong>6.2.2.1</strong> <strong>在</strong> <strong>classpath</strong> <strong>下定义</strong> <strong>db.properties</strong> <strong>文件</strong> jdbc.driver=com.mysql.jdbc.Driver jdbc.url=jdbc:mysql://localhost:3306/eesy jdbc.username=root jdbc.password=1234 <strong>6.2.2.2 properties</strong> <strong>标签配置</strong> &lt;!-- 配置连接数据库的信息 resource 属性：用于指定 properties 配置文件的位置，要求配置文件必须在类路径下 resource=&quot;jdbcConfig.properties&quot; url 属性： URL： Uniform Resource Locator 统一资源定位符 <a href="http://localhost:8080/mystroe/CategoryServlet" target="_blank" rel="noreferrer">http://localhost:8080/mystroe/CategoryServlet</a> URL 协议 主机 端口 URI URI：Uniform Resource Identifier 统一资源标识符 /mystroe/CategoryServlet 它是可以在 web 应用中唯一定位一个资源的路径 --&gt; &lt;properties url= <em>file:///D:/IdeaProjects/day02_eesy_01mybatisCRUD/src/main/resources/jdbcConfig.prop</em><em>erties&quot;</em>&gt; &lt;/properties&gt; <strong>6.2.3</strong> <strong>此时我们的</strong> <strong>dataSource</strong> <strong>标签就变成了引用上面的配置</strong> &lt;dataSource type=<em>&quot;POOLED&quot;</em>&gt; &lt;property name=<em>&quot;driver&quot;</em> value=<em>&quot;<strong>${jdbc.driver}</strong>&quot;</em>/&gt; &lt;property name=<em>&quot;url&quot;</em> value=<em>&quot;<strong>${jdbc.url}</strong>&quot;</em>/&gt; &lt;property name=<em>&quot;username&quot;</em> value=<em>&quot;<strong>${jdbc.username}</strong>&quot;</em>/&gt; &lt;property name=<em>&quot;password&quot;</em> value=<em>&quot;<strong>${jdbc.password}</strong>&quot;</em>/&gt; &lt;/dataSource&gt;传智播客——专注于 Java、.Net 和 Php、网页平面设计工程师的培训 <strong>6.3 typeAliases</strong>**（类型别名）** 在前面我们讲的 Mybatis 支持的默认别名，我们也可以采用自定义别名方式来开发。 <strong>6.3.1</strong> <strong>自定义别名：</strong> 在 SqlMapConfig.xml 中配置： &lt;typeAliases&gt; &lt;!-- 单个别名定义 --&gt; &lt;typeAlias alias=<em>&quot;user&quot;</em> type=<em>&quot;com.itheima.domain.User&quot;</em>/&gt; &lt;!-- 批量别名定义，扫描整个包下的类，别名为类名（首字母大写或小写都可以） --&gt; &lt;package name=<em>&quot;com.itheima.domain&quot;</em>/&gt; &lt;package name=<em>&quot;<strong>其它包</strong>&quot;</em>/&gt; &lt;/typeAliases&gt; <strong>6.4 mappers</strong>**（映射器）** <strong>6.4.1 &lt;mapper resource=&quot; &quot; /&gt;</strong> 使用相对于类路径的资源 如：&lt;mapper resource=&quot;com/itheima/dao/IUserDao.xml&quot; /&gt; <strong>6.4.2 &lt;mapper class=&quot; &quot; /&gt;</strong> 使用 mapper 接口类路径 如：&lt;mapper class=&quot;com.itheima.dao.UserDao&quot;/&gt; <strong>注意：此种方法要求</strong> <strong>mapper</strong> <strong>接口名称和</strong> <strong>mapper</strong> <strong>映射文件名称相同，且放在同一个目录中。</strong><strong>6.4.3 &lt;package name=&quot;&quot;/&gt;</strong> 注册指定包下的所有 mapper 接口 如：&lt;package name=&quot;cn.itcast.mybatis.mapper&quot;/&gt; <strong>注意：此种方法要求</strong> <strong>mapper</strong> <strong>接口名称和</strong> <strong>mapper</strong> <strong>映射文件名称相同，且放在同一个目录中。</strong></p></div>',1)])])}const q=o(n,[["render",a]]);export{c as __pageData,q as default};
